
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_bcgp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_bcgp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.321439727935365e+00, -4.239995504181421e+00, -4.125993583198140e+00, -3.968325780304732e+00, -3.754012943910555e+00, -3.469881859665807e+00, -3.106432293797510e+00, -2.664560306515081e+00, -2.163272825475426e+00, -1.636778006832709e+00, -1.104969198170127e+00, -7.134464131818906e-01, -6.037711370734072e-01, -5.048889689336518e-01, -3.753347525160210e-01, -2.471439955061490e-01, -1.349152297923424e-01, -4.962458685650174e-02, -1.081305611641345e-02, -1.216203794853054e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


